REMOVED_SNAPSHOT_DOCS = []
def api(endpoint, payload=None, method='POST'):
    args = ['gh', 'api', REPO + endpoint]
    if payload is not None:
        path = Path('/private/tmp/fwp-recovery-helper-api-input.json')
        path.write_text(json.dumps(payload))
        args += ['--method', method, '--input', str(path)]
    return json.loads(subprocess.check_output(args, text=True))

audit=api('/actions/runs/38219276272')
assert audit['head_sha']==OLD and audit['status']=='completed' and audit['conclusion']=='success'
assert all(Path(value).resolve().is_relative_to(Path('/private/tmp')) for value in HELPERS.values())
assert len(SUBJECT) <= 80 and '\n' not in SUBJECT
assert api('/git/ref/heads/' + BRANCH)['object']['sha'] == OLD
base = api('/git/commits/' + OLD)
data = {name: (ROOT / name).read_bytes() for name in DOCS}
data.update({name: Path(source).read_bytes() for name, source in HELPERS.items()})
# Reuse unchanged blobs and bound each tree request instead of resending history.
before = api('/git/trees/' + base['tree']['sha'] + '?recursive=1')
assert not before['truncated']
prior = {x['path']:x['sha'] for x in before['tree'] if x['type']=='blob'}
entries = []
for name, content in data.items():
    digest = hashlib.sha1(b'blob '+str(len(content)).encode()+b'\0'+content).hexdigest()
    if prior.get(name) != digest:
        entries.append(dict(path=name,mode='100644',type='blob',content=content.decode()))
entries += [dict(path=name,mode='100644',type='blob',sha=None) for name in REMOVED_SNAPSHOT_DOCS]
tree = dict(sha=base['tree']['sha'])
batch = []; batch_bytes = 0
for entry in entries:
    size = len(json.dumps(entry).encode())
    assert size < 4*1024*1024
    if batch and batch_bytes + size > 2*1024*1024:
        tree = api('/git/trees',dict(base_tree=tree['sha'],tree=batch))
        batch = []; batch_bytes = 0
    batch.append(entry); batch_bytes += size
if batch:
    tree = api('/git/trees',dict(base_tree=tree['sha'],tree=batch))
commit = api('/git/commits', dict(message=SUBJECT, tree=tree['sha'], parents=[OLD]))
assert commit['message'] == SUBJECT and len(commit['parents']) == 1
assert commit['parents'][0]['sha'] == OLD
files = api('/git/trees/' + tree['sha'] + '?recursive=1')
assert not files['truncated']
hashes = {entry['path']: entry['sha'] for entry in files['tree']}
assert all(name not in hashes for name in REMOVED_SNAPSHOT_DOCS)
for name, content in data.items():
    assert hashes[name] == hashlib.sha1(
        b'blob ' + str(len(content)).encode() + b'\0' + content).hexdigest(), name
ref = api('/git/refs/heads/' + BRANCH, dict(sha=commit['sha'], force=False), method='PATCH')
assert ref['object']['sha'] == commit['sha']
Path('/private/tmp/fwp-numerical-lookup-recovery-checkpoint.json').write_text(json.dumps(
    dict(head=commit['sha'], previous=OLD, branch=BRANCH,
         sourceHashes={name: hashlib.sha256(content).hexdigest()
                       for name, content in data.items()},
         stage='Recovery drafts retained; no native workload or new audit executed'),
    indent=2) + '\n')
print(commit['sha'])
